"""This file contains Classes with the functionality for the the Service Menu page objects"""

import logging
from interops.libraries.desktop.base_ui_page_object import BaseUIPageObject
from interops.libraries.integrity.pages.storedbeam_menu import DeliverStoredBeam
import interops.libraries.desktop.decorators as deco
from interops.libraries.desktop.application import ApplicationManager
import interops.libraries.integrity.integrity_objects as integrity_objects
import squishtest3 as sq


logger = logging.getLogger(__name__)

class ServiceMenuBar(BaseUIPageObject):

    application_name = "RTDShell"

    # ToT=Yes
    def ready(self):
        try:
            sq.waitForObjectExists(integrity_objects.service_Menubutton_Help)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_AdminLinac, 3000)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_SysAdmin, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_ServiceFunctions, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_Calibration, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_MachineConfig, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_MLC, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_ChangePassowrd, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_Save, 0)
            sq.waitForObjectExists(integrity_objects.service_Menubutton_LogOff, 0)
            return True
        except Exception:
            return False

    # ToT=Yes
    def service_functions(self):
        # 19-10-2017: sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_ServiceFunctions))
        super(ServiceMenuBar, self).mouseClick(integrity_objects.service_Menubutton_ServiceFunctions)

        sq.snooze(2)

    def system_adminin(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_SysAdmin))
        sq.snooze(2)

    @deco.app_ctx_function()
    def system_create_stored_beam(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.serviceFunctions_Menubutton_CreateStoredBeam))
        sq.snooze(2)

    @deco.app_ctx_function()
    def admin_linac(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_AdminLinac))
        sq.snooze(2)

    @deco.app_ctx_function()
    def enable_energies(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_EnableEnergies))
        sq.snooze(2)

    @deco.app_ctx_function()
    def enable_clinical_mode(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_EnableClinicalMode))
        sq.snooze(2)

    @deco.app_ctx_function()
    def disable_clinical_mode(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_DisableClinicalMode))
        sq.snooze(2)

    @deco.app_ctx_function()
    def callibration_menu(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.service_Menubutton_Calibration))
        sq.snooze(2)

    @deco.app_ctx_function()
    def beam_gen_stw(self):
        sq.mouseClick(sq.waitForObject(":Calibration_Menubutton_BeamGenSTW"))
        try:
            sq.mouseClick(sq.waitForObject("{text='Cancel' type='Button'}", 2000))
        except Exception:
            pass
        try:
            sq.mouseClick(sq.waitForObject("{text='OK' type='Button'}", 2000))
        except Exception:
            pass
        sq.snooze(2)
        self.beam_gen_tabs("   Graph   ")
        sq.snooze(2)

    @deco.app_ctx_function()
    def calibration_workflows(self):
        sq.mouseClick(sq.waitForObject(":Service_Menubutton_CalibrationWorkflows"))
        sq.snooze(2)

    @deco.app_ctx_function()
    def log_off(self):
        super(ServiceMenuBar, self).mouseClick(integrity_objects.service_Menubutton_LogOff)
        sq.snooze(2)
        try:
            super(ServiceMenuBar, self).mouseClick(integrity_objects.confirm_LogOff)
        except Exception:
            try:
                super(ServiceMenuBar, self).mouseClick(integrity_objects.service_Menubutton_LogOff)
                sq.snooze(2)
                super(ServiceMenuBar, self).mouseClick(integrity_objects.confirm_LogOff)
            except Exception:
                pass
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.no_Button, 2000))
        except Exception:
            pass

        try:
            sq.waitForObjectExists(integrity_objects.login_About_Button, 2000)
            return True
        except Exception as e:
            logger.exception("Login page not seen " + str(e))
            return False

    @deco.app_ctx_function()
    def view_restrictions(self):
        try:
            sq.mouseClick(sq.waitForObjectExists(":Inhibits"))
            sq.snooze(2)
            if sq.waitForObjectExists(":View_Restrictions.Header_lbl"):
                return True
            else:
                return False
        except Exception as e:
            logger.exception("Exception in ServiceMenuBar view_restrictions()" + str(e))
            return False

    @deco.app_ctx_function()
    def mlc(self):
        sq.mouseClick(sq.waitForObject(":Service_Menubutton_MLC"))
        sq.snooze(2)

    @deco.app_ctx_function()
    def display_shape_codes(self):
        sq.mouseClick(sq.waitForObject(":Service_Menubutton_Display_Shape_Code"))
        sq.snooze(2)

    @deco.app_ctx_function()
    def diagnostic_control(self):
        sq.mouseClick(sq.waitForObject(":Service_Menubutton_Diagnostic_Control"))
        sq.snooze(2)

    @deco.app_ctx_function()
    def beam_gen_tabs(self, tabs):
        sq.mouseClick(sq.waitForObject({"type": "TabItem", "text": tabs}))
        sq.snooze(5)

    @deco.app_ctx_function()
    def calibrate_gantry(self):
        sq.mouseClick(sq.waitForObject(":ServiceFunctions_Calibrate_Gantry"))
        sq.snooze(2)


class ServiceFunctionsMenuBar(BaseUIPageObject):

    application_name = "RTDShell"

    def ready(self):
        try:
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_BeamGenDiagInterface)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_CreateStoredBeam, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_DeliverStoredBeam, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_DeliverQuickBeam, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_ServicePages, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_MachineItem, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_MachineState, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_IntelockConfig, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_MachineItemPart, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_MachineParams, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_ServiceGraphing, 0)
            sq.waitForObjectExists(integrity_objects.serviceFunctions_Menubutton_BeamGenDiagnostics, 0)
            return True
        except Exception:
            return False

    # ToT=Yes
    def deliver_stored_beam(self):
        # sq.mouseClick(sq.waitForObject(integrity_objects.serviceFunctions_Menubutton_DeliverStoredBeam))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_DeliverStoredBeam)
        self.dsb = DeliverStoredBeam()
        return self.dsb

    def deliver_quick_beam(self):
        sq.mouseClick(sq.waitForObject(integrity_objects.serviceFunctions_Menubutton_DeliverQuickBeam))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_DeliverQuickBeam)

    def service_pages(self):
        # sq.mouseClick(sq.waitForObject(integrity_objects.serviceFunctions_Menubutton_MachineState))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_ServicePages)

    # ToT=Yes
    def select_machine_state(self):
        # sq.mouseClick(sq.waitForObject(integrity_objects.serviceFunctions_Menubutton_ServicePages))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_MachineState)

    def service_graph(self):
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_ServiceGraphing)

    def open_edit_machine_item_part(self):
        # sq.mouseClick(sq.waitForObject(":ServiceFunctions_Menubutton_ServicePages"))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_MachineItemPart)

    def create_edit_stored_beam(self):
        # sq.mouseClick(sq.waitForObject(":ServiceFunctions_Menubutton_CreateStoredBeam"))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_CreateStoredBeam)

    def adjust_machine_parameters(self):
        # sq.mouseClick(sq.waitForObject(":ServiceFunctions_Menubutton_ServicePages"))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_MachineParams)

    def beam_gen_diagnostics(self):
        # sq.mouseClick(sq.waitForObject(":ServiceFunctions_Menubutton_ServicePages"))
        super(ServiceFunctionsMenuBar, self).mouseClick(integrity_objects.serviceFunctions_Menubutton_BeamGenDiagnostics)

    def interlock_configuration_override(self):
        # sq.mouseClick(sq.waitForObject(":ServiceFunctions_Menubutton_ServicePages"))
        super(ServiceFunctionsMenuBar, self).mouseClick(":ServiceFunctions_Menubutton_IntelockConfig")


class ServicePages(BaseUIPageObject):

    application_name = "ServiceCore"

    def __init__(self):
        self.ready()

    def load_custom(self):
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.service_Page_Container_Custom_Button))
        except Exception:
            return False

    def ready(self):
        try:
            sq.waitForObjectExists(integrity_objects.service_Page_Container_Load_Button)
            sq.waitForObjectExists(integrity_objects.service_Page_Container_Go_To_Button, 0)
            sq.waitForObjectExists(integrity_objects.service_Page_Container_Unload_Button, 0)
            sq.waitForObjectExists(integrity_objects.dSP_Close, 0)
            sq.waitForObjectExists(integrity_objects.service_Page_Container_Print_Button, 0)
            sq.mouseClick(sq.waitForObject(integrity_objects.service_Page_Container_Load_Button))
            ApplicationManager.attach_to_running_appplication("ServiceCore.exe")
            sq.mouseClick({"type": "ScrollBar"})
        except Exception:
            return False

    @deco.app_ctx_function()
    def select_page(self, page):
        try:

            sq.waitForObjectExists(integrity_objects.svcPageSelection_list)
            sq.mouseClick(sq.waitForObject({"text": page}))
            sq.snooze(1)
            sq.mouseClick(sq.waitForObject(integrity_objects.svcPageSelection_OK))
            return True
        except Exception:
            return False

    def unload(self):
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.service_Page_Container_Unload_Button))
        except Exception:
            return False

    def close(self):
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.dSP_Close))
        except Exception:
            return False

    def dsp_print(self):
        try:
            sq.mouseClick(sq.waitForObject(integrity_objects.service_Page_Container_Print_Button))
        except Exception:
            return False


